-- NextLevel: demo Mini Tomás. Crear primero tomas@nextlevel.com en Authentication.
-- Copia sólo estadísticas de Milo; no copia fotos, contactos, mensajes, medidas ni prácticas privadas.
-- Alta atómica. Si ya existe la demo, aborta para conservar cualquier trabajo previo.
begin;
do $$
declare source_id uuid := 'e814cad8-7be8-45dd-8fdd-2d5dcc32bc96';
 demo_id uuid := 'de000000-0000-4000-8000-000000000011'; account_id uuid; matches integer;
 cols text; expr text;
begin
 select count(*),min(id::text)::uuid into matches,account_id from auth.users where lower(email)='tomas@nextlevel.com';
 if matches<>1 then raise exception 'Crear primero tomas@nextlevel.com en Authentication.'; end if;
 if exists(select 1 from public.players where user_id=account_id) then raise exception 'La cuenta ya tiene un perfil vinculado.'; end if;
 if exists(select 1 from public.players where id=demo_id) then raise exception 'La demo ya existe. No se sobrescribe.'; end if;
