 insert into public.players(id,name,dorsal,category,club,user_id) values(demo_id,'Tomás Pérez · DEMO',5,'Mini U11','Club Horizonte · DEMO',account_id);
 -- Columnas conocidas del registro deportivo; cualquier campo personal queda excluido.
 select string_agg(quote_ident(column_name),',' order by ordinal_position),
 string_agg(case column_name when 'player_id' then quote_literal(demo_id)||'::uuid' when 'torneo' then quote_literal('Mini · DEMO') when 'rival' then quote_literal('Rival ficticio · DEMO') else quote_ident(column_name) end,',' order by ordinal_position)
