 and column_name=any(array['player_id','cabb_partido_id','fecha','rival','torneo','es_local','resultado_eq','ganado','pts','minutos','faltas','val','source','synced_at','tl_in','tl_att','t2_in','t2_att','t3_in','t3_att','tc_in','tc_att','reb_tot','reb_def','reb_of','ast','stl','blk','to_perdidas']);
